using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class PlayerPlantingChecks {
 static void Require(bool ok,string reason){if(!ok)throw new Exception(reason);}
 [MenuItem("BWVR/Verify player planting model")]
 public static void VerifyModel(){
  var state=new ResourceState{wood=2,wheat=1};var farm=state.EnsureFarm("farm-0",Vector3.zero);string before=JsonUtility.ToJson(state);Require(state.CanPlantField(farm.id)&&JsonUtility.ToJson(state)==before,"Preview mutated resources");
  Require(state.PlantField(farm.id)&&farm.farmPrepared&&farm.growing&&farm.plantings==1&&state.wheat==0&&state.wood==0&&state.seedUsed==1&&state.farmWoodUsed==2,"Combined preparation and seed payment incorrect");
  before=JsonUtility.ToJson(state);Require(!state.PlantField(farm.id)&&JsonUtility.ToJson(state)==before,"Growing plot replayed payment");var save=JsonUtility.FromJson<ResourceState>(before);Require(save.Valid()&&save.Find(farm.id).growing&&!save.PlantField(farm.id),"Saved planting replayed");
  save.Grow(farm.id,90);Require(Mathf.Abs(save.Find(farm.id).growth-.5f)<.001f&&save.Find(farm.id).remaining==0,"Planted crop did not use existing growth");save.Grow(farm.id,90);Require(save.Find(farm.id).remaining==12&&save.Find(farm.id).regrown==1&&!save.Grow(farm.id,90),"Crop matured more than once");
  var noSeed=new ResourceState{wood=2,wheat=0};noSeed.EnsureFarm("farm-0",Vector3.zero);before=JsonUtility.ToJson(noSeed);Require(!noSeed.PlantField("farm-0")&&before==JsonUtility.ToJson(noSeed),"Failed sowing consumed timber");var noWood=new ResourceState{wood=1,wheat=1};noWood.EnsureFarm("farm-0",Vector3.zero);before=JsonUtility.ToJson(noWood);Require(!noWood.PlantField("farm-0")&&before==JsonUtility.ToJson(noWood),"Failed preparation consumed seed");
  var old=new ResourceState{wheat=1};var field=old.Ensure("wheat-old",VillageResource.Wheat);Require(!old.PlantField(field.id),"Standing field was overwritten");field.remaining=0;Require(old.PlantField(field.id)&&old.seedUsed==1&&old.farmWoodUsed==0&&old.Valid(),"Existing depleted field charged timber");Require(!old.PlantField("missing")&&!old.PlantField(null),"Unknown plot accepted");
  Debug.Log("BWVR_PLAYER_PLANT_MODEL_PASS: atomic seed/timber cost, read-only preview, no partial payment/replay, existing-field reuse, saved growth and once-only maturity");
 }
 [MenuItem("BWVR/Verify player seed tool (Play mode)")]
 public static void VerifyRuntime(){
  Require(EditorApplication.isPlaying,"Enter Play mode");var palette=UnityEngine.Object.FindAnyObjectByType<GodToolPalette>();var slice=palette.GetComponentInParent<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)field.GetValue(slice);god.Interrupt("Seed tool QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};field.SetValue(slice,test);foreach(var gatherer in world.Gatherers){gatherer.GetComponent<VillagerSocial>().ResetTask();gatherer.GetComponent<VillagerExploration>().ResetTask();gatherer.GetComponent<VillagerBlockPlay>().ResetTask();}world.ResetWorld();var miracles=slice.GetComponentInChildren<DivineIntervention>();
  try{
   palette.Cancel();palette.Process(new Ray(Vector3.zero,Vector3.down),false,true,false,.02f,false);var node=world.sources.First(s=>s.expansion);var record=test.Resources.Find(node.id);test.Resources.wood=8;test.Resources.wheat=4;world.Refresh();
   string before=JsonUtility.ToJson(test);Require(world.CanPlayerPlant(node.at,out _)&&before==JsonUtility.ToJson(test),"World preview changed state");test.paused=true;string paused=JsonUtility.ToJson(test);Require(!palette.Apply(SpiritualTool.PlantSeeds,null,node.at)&&paused==JsonUtility.ToJson(test)&&!record.farmPrepared,"Paused planting applied");test.paused=false;miracles.Suspended=true;Require(!palette.Apply(SpiritualTool.PlantSeeds,null,node.at),"Suspended planting applied");miracles.Suspended=false;
   Require(!world.CanPlayerPlant(new Vector3(float.NaN,0,0),out _)&&!world.CanPlayerPlant(node.at+Vector3.up,out _),"Nonfinite/air planting accepted");
   var actor=world.Gatherers[0];test.Resources.wheat=1;Require(actor.TryPrepareFarm(node),"Could not reserve plot and seeds");Require(!world.CanPlayerPlant(node.at,out _),"Seed tool stole villager plot");var other=world.sources.First(s=>s.expansion&&s!=node);Require(!world.CanPlayerPlant(other.at,out _),"Seed tool spent reserved seed");actor.Cancel();test.Resources.wheat=4;test.Resources.wood=2;Require(actor.TryPrepareFarm(node)&&!world.CanPlayerPlant(other.at,out _),"Seed tool spent reserved timber");actor.Cancel();test.Resources.wood=8;
   var ray=new Ray(node.at+Vector3.up*world.Navigation.Scale*20,Vector3.down);palette.Select(SpiritualTool.PlantSeeds);var symbol=(GameObject)typeof(GodToolPalette).GetField("wand",flags).GetValue(palette);Require(symbol.GetComponentsInChildren<MeshRenderer>().Length>0&&symbol.GetComponentsInChildren<Collider>().Length==0&&symbol.GetComponentsInChildren<CarryItem>().Length==0,"Seed pouch lost art or gained world ownership");palette.Process(ray,true,true,false,.02f,false);Require(!record.growing,"Selecting while held planted seed");palette.Process(ray,false,true,false,.02f,false);float energy=test.Hybrid.energy;int uses=palette.Uses;
   palette.Process(ray,true,true,false,.02f,false);Require(record.growing&&record.farmPrepared&&record.plantings==1&&test.Resources.seedUsed==1&&test.Resources.farmWoodUsed==2&&test.Resources.wood==6&&test.Resources.wheat==3&&palette.Uses==uses+1&&test.Hybrid.energy==energy,"Seed gesture did not plant with exact finite payment");
   var second=world.sources.First(s=>s.expansion&&s!=node);var secondRay=new Ray(second.at+Vector3.up*world.Navigation.Scale*20,Vector3.down);for(int i=0;i<20;i++){test.Hybrid.time+=.05f;palette.Process(secondRay,true,true,false,.05f,false);}Require(test.Resources.seedUsed==2&&test.Resources.Find(second.id).growing,"Held seed tool did not paint the next eligible plot");
   palette.Process(secondRay,false,true,false,.02f,false);test.Hybrid.time+=1;palette.Process(secondRay,true,true,false,.02f,false);Require(test.Resources.seedUsed==2,"Held/rearmed tool repaid an already growing plot");
   var third=world.sources.First(s=>s.expansion&&s!=node&&s!=second);Require(palette.Apply(SpiritualTool.PlantSeeds,null,third.at),"Third bounded planting failed");var fourth=world.sources.First(s=>s.expansion&&s!=node&&s!=second&&s!=third);float timber=test.Resources.wood,seeds=test.Resources.wheat;Require(!world.CanPlayerPlant(fourth.at,out _)&&!palette.Apply(SpiritualTool.PlantSeeds,null,fourth.at)&&test.Resources.wood==timber&&test.Resources.wheat==seeds,"Growing-plot budget exceeded or rejected attempt charged");
   var copy=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(copy.Valid()&&copy.Resources.Find(node.id).growing&&copy.Resources.seedUsed==3&&copy.Hybrid.Evidence.completedCreatureActions==0&&copy.Hybrid.Evidence.playerMiracles==0,"Planting save/attribution invalid");float growth=record.growth;world.Advance(10,true);Require(record.growth==growth,"Paused planted crop grew");world.Advance(10,false);Require(record.growth>growth&&node.sapling.gameObject.activeSelf&&node.visual.gameObject.activeSelf,"Planted soil/crop visuals or growth missing");
   palette.Process(ray,true,false,false,.02f,true);Require(!palette.Selected.HasValue&&!palette.View.activeSelf,"Tracking loss did not cancel seed tool");palette.Cancel();var previews=palette.transform.Find("Private planting plot previews");Require(previews!=null&&!previews.gameObject.activeSelf&&previews.GetComponentsInChildren<Collider>(true).Length==0&&previews.childCount<=12,"Plant previews leaked colliders, count or visibility");
   Debug.Log("BWVR_PLAYER_PLANT_RUNTIME_PASS: preview, finite/pause/suspend gates, villager reservations, selection/hold/rearm, three-plot budget, exact payment, visuals, saved growth, no miracle/creature credit, tracking cleanup and bounded private previews");
  }finally{miracles.Suspended=false;palette.Cancel();field.SetValue(slice,original);world.ResetWorld();god.Interrupt("Seed tool QA complete");}
 }
}
}
